-- ── story 4-2c: the backorder follow-on ─────────────────────────────────────
-- Generated by drizzle-kit (the three column statements and the index
-- statements) and hand-amended around the generated part: the fail-fast
-- guard, the pairing CHECK, the statement order (the renamed identity indexes
-- are created BEFORE the old ones are dropped) and the post-migration probe
-- (drizzle-kit is blind to CHECKs; `bun run db:generate` afterwards reports
-- "No schema changes").
--
-- Three columns on `orders` (all NULL on a root order):
--   * `follow_on_of_order_id uuid NULL` — the parent: the order whose short
--     dispatch opened this follow-on for its unshipped remainder.
--   * `follow_on_root_order_id uuid NULL` — the chain's root (the client's
--     original order): the label's short id, the channel cancellation's routing.
--   * `follow_on_seq integer NULL` — 1 for the root's follow-on, 2 for that
--     one's, …: the label suffix `-BO{seq}`.
-- CHECK `orders_follow_on_pairing` (NOT VALID): all three null, or all three
-- set with `follow_on_seq >= 1`. Every existing row carries three NULLs, which
-- the CHECK admits by construction (guide §3, the 0093 rule) — no VALIDATE
-- under this migration's lock; a later deploy validates it (PENDING).
--
-- The two identity indexes count ROOT orders only (a follow-on copies its
-- root's client order number and channel event). `migrate-deploy` refuses a
-- same-name rebuild (`rebuilt-in-pending`, `name-collision`), so each gets a
-- NEW name, created first, and the old one is dropped after:
--   orders_source_event_unique          → orders_source_event_root_unique
--   orders_client_order_ref_live_unique → orders_client_order_ref_live_root_unique
-- (src/modules/outbound/order.command.ts catches violations by these names.)
-- Plus `orders_follow_on_of_unique` (one follow-on per parent — the dispatch
-- race backstop), `orders_follow_on_root_idx` (a chain by its root) and
-- `orders_accepted_tenant_warehouse_idx` (the allocation sweep's driving read).
--
-- Every build is a plain (non-concurrent) build inside the migrator's one
-- transaction — the 0088 precedent. On a large live `orders` table, pre-build
-- each new one by hand `CREATE … CONCURRENTLY IF NOT EXISTS` under the same
-- name first (DEPLOY.md §5; the migrator prints the statement); `IF NOT
-- EXISTS` then skips it here. PENDING's live-deploy runbook entry names them.

-- ── 0. fail-fast: already applied ────────────────────────────────────────
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.columns
		 WHERE table_schema = 'public' AND table_name = 'orders'
		   AND column_name IN ('follow_on_of_order_id', 'follow_on_root_order_id', 'follow_on_seq')
	) THEN
		RAISE EXCEPTION 'migration 0104: orders already has a follow-on column — this migration has already been applied.';
	END IF;
END $$;
--> statement-breakpoint
ALTER TABLE "orders" ADD COLUMN "follow_on_of_order_id" uuid;--> statement-breakpoint
ALTER TABLE "orders" ADD COLUMN "follow_on_root_order_id" uuid;--> statement-breakpoint
ALTER TABLE "orders" ADD COLUMN "follow_on_seq" integer;--> statement-breakpoint
-- ── hand-amended: the pairing CHECK (migration SQL only), NOT VALID ──────
ALTER TABLE "orders" ADD CONSTRAINT "orders_follow_on_pairing" CHECK (
	("follow_on_of_order_id" IS NULL AND "follow_on_root_order_id" IS NULL AND "follow_on_seq" IS NULL)
	OR ("follow_on_of_order_id" IS NOT NULL AND "follow_on_root_order_id" IS NOT NULL AND "follow_on_seq" IS NOT NULL AND "follow_on_seq" >= 1)
) NOT VALID;--> statement-breakpoint
-- ── the renamed identity indexes: new names first, then the old dropped ──
CREATE UNIQUE INDEX IF NOT EXISTS "orders_source_event_root_unique" ON "orders" USING btree ("tenant_id","integration_id","external_event_id") WHERE integration_id is not null and external_event_id is not null and follow_on_of_order_id is null;--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "orders_client_order_ref_live_root_unique" ON "orders" USING btree ("tenant_id","client_order_ref","client_id") WHERE client_order_ref is not null and status <> 'cancelled' and follow_on_of_order_id is null;--> statement-breakpoint
DROP INDEX "orders_source_event_unique";--> statement-breakpoint
DROP INDEX "orders_client_order_ref_live_unique";--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "orders_follow_on_of_unique" ON "orders" USING btree ("tenant_id","follow_on_of_order_id") WHERE follow_on_of_order_id is not null;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "orders_follow_on_root_idx" ON "orders" USING btree ("tenant_id","follow_on_root_order_id") WHERE follow_on_root_order_id is not null;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "orders_accepted_tenant_warehouse_idx" ON "orders" USING btree ("tenant_id","warehouse_id","created_at","id") WHERE status = 'accepted';--> statement-breakpoint
-- ── the post-migration assertion (the 0093 model) ─────────────────────────
-- Made-up uuids. (a) The CHECK is present and NOT VALID; the two old names
-- are gone and the two new ones carry the root predicate. (b) The accepted
-- shapes — a root on a channel event and a root with a client number, each
-- with a follow-on sharing its identity, and a second-generation follow-on —
-- are inserted and rolled back by a sentinel exception. (c) Inside the same
-- rolled-back block, the three uniqueness refusals, each by its named
-- constraint. (d) The pairing refusals — every partial combination of the
-- three columns, and a seq of 0 — each in its own subtransaction.
DO $$
DECLARE
	t uuid := gen_random_uuid();
	w uuid := gen_random_uuid();
	c uuid := gen_random_uuid();
	integ uuid := gen_random_uuid();
	root_a uuid := gen_random_uuid();
	root_b uuid := gen_random_uuid();
	fo_a uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
	n int;
	second_follow_on text := 'nothing';
	second_root_event text := 'nothing';
	second_root_ref text := 'nothing';
BEGIN
	-- (a) the CHECK, NOT VALID.
	SELECT count(*) INTO n FROM pg_constraint
	 WHERE conrelid = 'public.orders'::regclass AND conname = 'orders_follow_on_pairing' AND contype = 'c' AND NOT convalidated;
	IF n <> 1 THEN
		RAISE EXCEPTION 'migration 0104: expected orders_follow_on_pairing present and NOT VALID.';
	END IF;
	SELECT count(*) INTO n FROM pg_class
	 WHERE relkind = 'i' AND relname IN ('orders_source_event_unique', 'orders_client_order_ref_live_unique');
	IF n <> 0 THEN
		RAISE EXCEPTION 'migration 0104: a pre-4-2c identity name survived (% of 2).', n;
	END IF;
	SELECT count(*) INTO n FROM pg_class
	 WHERE relkind = 'i' AND relname IN ('orders_source_event_root_unique', 'orders_client_order_ref_live_root_unique')
	   AND pg_get_indexdef(oid) LIKE '%follow_on_of_order_id IS NULL%';
	IF n <> 2 THEN
		RAISE EXCEPTION 'migration 0104: expected both root identity definitions with the root predicate, found %.', n;
	END IF;
	-- (b) + (c) the accepted shapes, then the uniqueness refusals beside them.
	BEGIN
		INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","source","integration_id","external_event_id")
		VALUES (root_a, t, c, w, 'ingested', integ, '5001');
		INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","source","integration_id","external_event_id",
		                      "follow_on_of_order_id","follow_on_root_order_id","follow_on_seq")
		VALUES (fo_a, t, c, w, 'ingested', integ, '5001', root_a, root_a, 1);
		INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","source","integration_id","external_event_id",
		                      "follow_on_of_order_id","follow_on_root_order_id","follow_on_seq")
		VALUES (gen_random_uuid(), t, c, w, 'ingested', integ, '5001', fo_a, root_a, 2);
		INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","client_order_ref")
		VALUES (root_b, t, c, w, '1042');
		INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","client_order_ref",
		                      "follow_on_of_order_id","follow_on_root_order_id","follow_on_seq")
		VALUES (gen_random_uuid(), t, c, w, '1042', root_b, root_b, 1);
		BEGIN
			INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","follow_on_of_order_id","follow_on_root_order_id","follow_on_seq")
			VALUES (gen_random_uuid(), t, c, w, root_a, root_a, 1);
		EXCEPTION WHEN unique_violation THEN
			GET STACKED DIAGNOSTICS second_follow_on = CONSTRAINT_NAME;
		END;
		BEGIN
			INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","source","integration_id","external_event_id")
			VALUES (gen_random_uuid(), t, c, w, 'ingested', integ, '5001');
		EXCEPTION WHEN unique_violation THEN
			GET STACKED DIAGNOSTICS second_root_event = CONSTRAINT_NAME;
		END;
		BEGIN
			INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","client_order_ref")
			VALUES (gen_random_uuid(), t, c, w, '1042');
		EXCEPTION WHEN unique_violation THEN
			GET STACKED DIAGNOSTICS second_root_ref = CONSTRAINT_NAME;
		END;
		RAISE EXCEPTION USING ERRCODE = 'P0104', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR not_null_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0104: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0104' THEN
			NULL;
	END;
	IF second_follow_on IS DISTINCT FROM 'orders_follow_on_of_unique' THEN
		RAISE EXCEPTION 'migration 0104: a second follow-on of one parent was refused by % (expected orders_follow_on_of_unique).', second_follow_on;
	END IF;
	IF second_root_event IS DISTINCT FROM 'orders_source_event_root_unique' THEN
		RAISE EXCEPTION 'migration 0104: a second root on one channel event was refused by % (expected orders_source_event_root_unique).', second_root_event;
	END IF;
	IF second_root_ref IS DISTINCT FROM 'orders_client_order_ref_live_root_unique' THEN
		RAISE EXCEPTION 'migration 0104: a second live root on one client number was refused by % (expected orders_client_order_ref_live_root_unique).', second_root_ref;
	END IF;
	-- (d) the pairing refusals, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY['seq without parent', 'parent without seq', 'seq 0', 'root without parent', 'parent only', 'root only', 'parent and seq without root'] LOOP
		refused_by := NULL;
		expected := 'orders_follow_on_pairing';
		BEGIN
			CASE probe
				WHEN 'seq without parent' THEN
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","follow_on_seq")
					VALUES (gen_random_uuid(), t, c, w, 1);
				WHEN 'parent without seq' THEN
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","follow_on_of_order_id","follow_on_root_order_id")
					VALUES (gen_random_uuid(), t, c, w, gen_random_uuid(), gen_random_uuid());
				WHEN 'seq 0' THEN
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","follow_on_of_order_id","follow_on_root_order_id","follow_on_seq")
					VALUES (gen_random_uuid(), t, c, w, gen_random_uuid(), gen_random_uuid(), 0);
				WHEN 'root without parent' THEN
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","follow_on_root_order_id","follow_on_seq")
					VALUES (gen_random_uuid(), t, c, w, gen_random_uuid(), 1);
				WHEN 'parent only' THEN
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","follow_on_of_order_id")
					VALUES (gen_random_uuid(), t, c, w, gen_random_uuid());
				WHEN 'root only' THEN
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","follow_on_root_order_id")
					VALUES (gen_random_uuid(), t, c, w, gen_random_uuid());
				WHEN 'parent and seq without root' THEN
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","follow_on_of_order_id","follow_on_seq")
					VALUES (gen_random_uuid(), t, c, w, gen_random_uuid(), 1);
			END CASE;
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0104: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "orders" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0104: a probe row survived.';
	END IF;
END $$;
